tile_navigation.query:
timeseries {
  speed   = avg(`ship.speed.knots`),
  heading = avg(`ship.heading.degrees`)
}, by: {ship_id}
| filter isNull(array($ship)[0]) or in(ship_id, array($ship))

tile_crew.query:
timeseries {
  crew   = avg(`ship.crew.active`),
  drones = avg(`ship.drone.count`)
}, by: {ship_id}
| filter isNull(array($ship)[0]) or in(ship_id, array($ship))

tile_hull_zones.query:
timeseries {
  zone1_bow      = avg(`ship.dc.hull.zone1.percent`),
  zone2_forward  = avg(`ship.dc.hull.zone2.percent`),
  zone3_midships = avg(`ship.dc.hull.zone3.percent`),
  zone4_eng_room = avg(`ship.dc.hull.zone4.percent`),
  zone5_aft      = avg(`ship.dc.hull.zone5.percent`)
}, by: {ship_id}
| filter isNull(array($ship)[0]) or in(ship_id, array($ship))

